start('استاد نصیری','nasiri',[('انتقال و شناسایی','فرض مسئله، مثال‌ها و آنتی‌ژن‌ها'),('بیماری‌زایی و دهان','مکانیسم‌ها و استدلال تشریحی')])
A(1,'قطره و ذرهٔ معلق در فرض سؤال',[3,5], 'این فایل اساساً پرسش و پاسخ است؛ درس‌ها توضیح کوتاه برای آمادگی پاسخ نوشتاری‌اند.',[
 ['فرض','A با قطرهٔ درشت و B با ذرهٔ معلق کوچک‌تر در مسئله تعریف شده‌اند.'],['تهویه','طبق پاسخنامه، ماندگاری بیشتر B در هوا سبب حساسیت بیشتر انتشار به تهویه می‌شود.'],['محل رسوب','در پاسخنامه، ذرهٔ کوچک‌تر امکان رسیدن به راه هوایی پایین‌تر دارد؛ این به تنهایی گونه یا نوع پنومونی را تعیین نمی‌کند.'],['فاصله','A با مواجههٔ نزدیک‌تر مرتبط شده است؛ «سرعت آلودگی» را از احتمال مواجهه جدا نگه دار.'],['ماسک در پاسخ منبع','برای A ماسک جراحی و برای B نوع N95 ذکر شده؛ این جوابِ فرض سؤال است، نه دستور یکسان برای هر مواجهه.'] ],
 'کوچک‌تر و معلق‌تر: تهویه و رسوب عمقی؛ درشت‌تر: مواجههٔ نزدیک.',
 [('تهویه چرا در فرض B مهم‌تر است؟','پاسخ منبع به ماندگاری و تجمع ذرات کوچک در هوا تکیه دارد؛ حذف هوا و رقیق‌سازی در این مدل اهمیت بیشتری پیدا می‌کند.',['ماندگاری','تجمع','فرض مسئله']),('رسوب عمقی چه چیزی را ثابت نمی‌کند؟','به تنهایی نام عامل، قطعیت پنومونی لوبار یا شدت بیماری را ثابت نمی‌کند؛ فقط یکی از عوامل مواجهه و محل رسوب است.',['محل','عامل','عدم قطعیت'])],warning=('حد عددی و ماسک','تقسیم‌بندی قطعی زیر ۵ میکرون، فاصلهٔ ثابت و کافی‌بودن همیشگی یک ماسک، ساده‌سازی پاسخنامه‌اند؛ این راهنما همان مدل آموزشی را با قید حفظ کرده است.'))
A(1,'مثال‌های انتروباکتری و آنتی‌ژن‌ها',[3,5], 'هر مثال را با ویژگی مورد سؤال جفت کن؛ یک نام می‌تواند در چند ردیف درست باشد.',[
 ['دوز کم و فردبه‌فرد','شیگلا، طبق پاسخنامه'],['خزنده یا ماکیان','سالمونلا'],['فلور روده و کلنی صورتی مک‌کانکی','اشریشیا کلی، انتروباکتر و کلبسیلا در مثال‌های منبع؛ دو ویژگی مستقل‌اند.'],['H','آنتی‌ژن تاژکی و ارتباط با حرکت'],['O','جزء سطحی مرتبط با دیواره/LPS؛ پاسخنامه فقط دیواره می‌گوید.'],['K','آنتی‌ژن کپسولی و فرار از فاگوسیتوز'],['Vi','پاسخنامه سالمونلا می‌نویسد، اما سؤال گونه می‌خواهد؛ سطح پاسخ کافی نیست.'] ],
 'H حرکت، O دیواره، K کپسول؛ مثال‌ها را با معیار همراه بنویس.',
 [('چرا فلوربودن و صورتی‌بودن یک مفهوم نیستند؟','اولی جایگاه زیستی و دومی نتیجهٔ افتراقی محیط در سؤال است؛ ممکن است یک عامل هر دو ویژگی را داشته باشد.',['زیستگاه','نتیجهٔ محیط']),('H، O و K را مقایسه کنید.','H با تاژک، O با پوشش دیواره‌ای/LPS و K با کپسول مرتبط است؛ کارکرد و جایگاه مشترک نیستند.',['جایگاه','حرکت','کپسول'])],warning=('پاسخ ناقص Vi','نام جنس سالمونلا در پاسخنامه، درخواست «کدام گونه» را کامل پاسخ نمی‌دهد؛ بدون منبع دیگر گونهٔ نهایی را از خود اضافه نکرده‌ایم.'))
A(2,'مراحل بیماری‌زایی و دفاع اکسیداتیو',[3,5,6], 'فهرست مراحل را به زنجیره تبدیل کن؛ عامل چسبندگی، آنزیم حفاظتی و سم نقش یکسانی ندارند.',[
 ['توالی جزوه','اتصال و استقرار با پیلی/فیمبریا؛ فرآورده‌های التهابی؛ تهاجم؛ فرار از دفاع؛ انتشار و علامت'],['شکل سؤال ۵','فاگوسیت و مواد اکسیدکننده را نشان می‌دهد؛ پاسخنامه کاتالاز را عامل موردنظر می‌داند.'],['کاتالاز','اثر بر پراکسید هیدروژن و کمک به بقا؛ به معنی خنثی‌کردن همهٔ مواد اکسیدکننده نیست.'],['AB','A بخش فعال و B بخش اتصال در پاسخنامه'],['سامانهٔ ترشحی نوع ۳','انتقال اثرگذار به سلول و تغییر مسیرهای سلولی در شرح مفهومی منبع'],['سوپرآنتی‌ژن','فعال‌سازی گستردهٔ T و سیتوکین، پاسخ سؤال؛ وجود آن را به همهٔ اعضای خانواده تعمیم نده.'],['تب تیفوئید','ورود گوارشی، عبور از سلول M، بقا در ماکروفاژ، انتشار لنفی/خونی و التهاب سیستمیک با تب و بزرگی کبد/طحال در روایت متن'] ],
 'بچسب، مستقر شو، از دفاع عبور کن و منتشر شو؛ A فعال، B اتصال.',
 [('AB و نوع ۳ چه تفاوتی دارند؟','AB توصیف نقش بخش‌های سم است؛ نوع ۳ یک سامانهٔ انتقال اثرگذار به سلول است. این دو محور ساختار/انتقال را یکی نمی‌کنیم.',['بخش‌های سم','سامانهٔ انتقال']),('چرا کاتالاز در شکل مهم است؟','به تجزیهٔ پراکسید هیدروژن و کاهش بخشی از فشار اکسیداتیو مرتبط است؛ نه حذف همهٔ دفاع ماکروفاژ.',['پراکسید','بقا','محدودیت'])],warning=('ترشح و فراگیری','اندوتوکسین را مانند یک پروتئین ترشحی معمول یا سوپرآنتی‌ژن را ویژگی همهٔ خانواده ننویس. ترتیب مراحل و نقش کاتالاز در پاسخنامه نیز مدل ساده‌شدهٔ آموزش است.'))
A(2,'دهان، باکتریمی و کنترل',[4,6], 'آسیب مخاط، زمینهٔ بیمار و کنترل مصرف دارو سه محور سؤال‌های پایانی‌اند.',[
 ['پاکت پریودنتال','وجود جمعیت میکروبی همراه با آسیب/خونریزیِ سد، امکان ورود به خون را در شرح منبع مطرح می‌کند.'],['پرخطرهای فهرست','دیابت و بیماری سیستمیک شدید/سالمندی؛ پیوند و شیمی‌درمانی؛ دریچهٔ مصنوعی'],['محل‌های دهانی','آبسه، کانال ریشهٔ نکروزه، استوماتیت مرتبط با پروتز و زخم در نقص ایمنی، نمونه‌های پاسخنامه‌اند.'],['راه ورود','منبع مسیر مدفوعی–دهانی و امکان استقرار دهانی را مطرح می‌کند؛ از این عبارت علت واحد همهٔ این ضایعات را نتیجه نگیر.'],['مدیریت مصرف','مصرف نامناسب می‌تواند انتخاب و گسترش گروه‌های مقاوم مانند ESBL و CRE را تقویت کند.'],['نشانهٔ سیستمیک','رنگ‌پریدگی، خونریزی لثه و زخم، اختصاصی یک عامل نیستند؛ منبع بررسی زمینه از جمله HUS را مطرح می‌کند.'],['کم‌آسیب','کاهش آسیب بافتی در مداخله، راه احتمالی ورود به خون را محدود می‌کند؛ تضمین حذف باکتریمی نیست.'] ],
 'سد و زمینه؛ نشانهٔ دهانی را در زمینهٔ کل بیمار بخوان.',
 [('چرا پاکت در فرض جزوه با باکتریمی مرتبط است؟','جمعیت موجود با دست‌کاری و آسیب سد ممکن است به خون راه پیدا کند؛ نقش التهاب و زمینهٔ بیمار جداگانه مهم‌اند.',['جمعیت','آسیب سد','زمینه']),('چرا مدیریت مصرف دارو اهمیت دارد؟','انتخاب و انتشار مقاومت، درمان را دشوار می‌کند؛ مصرف سنجیده و کنترل انتقال کنار هم‌اند.',['انتخاب','انتشار','درمان'])],warning=('انتساب دهانی و HUS','هر استوماتیت پروتز یا زخم را به انتروباکتری نسبت نده؛ فهرست پاسخنامه احتمال را مطرح می‌کند. علائم گفته‌شده اختصاصی HUS نیستند و ربط مستقیم LPS به ورود آسان به خون نیز ساده‌سازی است.'))
src=[
 Q('۱. در فرض A قطره‌ای و B ذرهٔ معلق، تهویه، رسوب، ماسک و مواجههٔ نزدیک را مقایسه کنید.','طبق پاسخنامه: تهویهٔ ضعیف بیشتر B را مطرح می‌کند؛ رسیدن به آلوئول در مدل B؛ برای A ماسک جراحی و B نوع N95 در پاسخ آمده؛ مواجههٔ نزدیک‌تر با A برجسته است. حدود عددی و کفایت حفاظت، فرض آموزشی‌اند.',['چهار محور','پاسخ متناسب با فرض','قید ساده‌سازی'],[3,5],'پرسش ۱ منبع؛ چهار بخش'),
 Q('۲. برای دوز کم فردبه‌فرد، انتقال از خزنده/ماکیان، فلور روده و کلنی صورتی مثال بزنید.','به ترتیب پاسخنامه: شیگلا؛ سالمونلا؛ اشریشیا کلی/انتروباکتر/کلبسیلا؛ همان سه نام برای کلنی صورتی در مثال‌ها.',['چهار معیار','مثال متناسب'],[3,5],'پرسش ۲ منبع؛ چهار بخش'),
 Q('۳. آنتی‌ژن حرکت، Vi، جایگاه O و نام آنتی‌ژن کپسولی چیست؟','حرکت: H؛ Vi: پاسخنامه فقط سالمونلا می‌گوید و گونه مشخص نیست؛ O: دیواره در جواب، مرتبط با LPS در درس؛ کپسول: K.',['H','Vi ناقص','O','K'],[3,5],'پرسش ۳ منبع؛ دارای پاسخ ناقص'),
 Q('۴. مراحل بیماری‌زایی را نام ببرید.','اتصال و استقرار، اثر فرآورده‌های التهابی، تهاجم بافتی، فرار از دفاع و انتشار با علامت؛ این توالیِ پاسخنامه است و برای همهٔ گونه‌ها شکل یکسان الزامی ندارد.',['اتصال','اثر','تهاجم','دفاع','انتشار'],[3,5],'پرسش ۴ منبع'),
 Q('۵. شکل، کدام عامل را نشان می‌دهد؟','کلید پاسخ، کاتالاز است: کاهش اثر پراکسید هیدروژن در فشار اکسیداتیو فاگوسیت؛ شکل را اثبات حذف همهٔ مواد مانند HOCl ندان.',['کاتالاز','پراکسید','بقا'],[3,5],'پرسش تصویری ۵ منبع'),
 Q('۶. بخش‌های AB، نوع ۳ و عامل تحریک گستردهٔ T را توضیح دهید.','A فعال، B اتصال؛ سامانهٔ نوع ۳ انتقال اثرگذار و تغییر پیام‌رسانی سلول؛ سوپرآنتی‌ژن پاسخ بخش فعال‌سازی گستردهٔ T است.',['A/B','سامانه','سوپرآنتی‌ژن'],[3,5,6],'پرسش ۶ منبع؛ سه بخش'),
 Q('۷. تب تیفوئید چگونه توضیح داده شده است؟','ورود با آب/غذا، عبور روده‌ای با سلول M، بقا در ماکروفاژ، گسترش با خون و لنف و التهاب سیستمیک، تب و بزرگی کبد و طحال.',['ورود','M','ماکروفاژ','انتشار','علامت'],[4,6],'پرسش ۷ منبع'),
 Q('۸. چرا پاکت پریودنتال خطر باکتریمی را افزایش می‌دهد؟ دو گروه پرخطر نام ببرید.','آسیب و خونریزی سد در حضور جمعیت میکروبی، مسیر ورود به خون را مطرح می‌کند. دو نمونه: پیوند/شیمی‌درمانی و دریچهٔ مصنوعی؛ دیابت و بیماری شدید نیز در فهرست‌اند.',['سد','جمعیت','دو گروه'],[4,6],'پرسش ۸ منبع'),
 Q('۹. عفونت‌های دهانی و راه انتقال مرتبط را نام ببرید.','آبسه، عفونت کانال نکروزه، استوماتیت پروتز و زخم در نقص ایمنی در پاسخنامه‌اند؛ مسیر مدفوعی–دهانی و استقرار در دهان ذکر شده است. نقش این خانواده در همهٔ نمونه‌ها قطعی و انحصاری نیست.',['چهار نمونه','راه منبع','عدم تعمیم'],[4,6],'پرسش ۹ منبع'),
 Q('۱۰. مدیریت مصرف، توجه به نشانه‌های سیستمیک و روش کم‌آسیب چرا مهم‌اند؟','مدیریت مصرف انتخاب/انتشار مقاومت را محدود می‌کند؛ نشانه‌های دهانی ممکن است زمینهٔ سیستمیک را مطرح کنند ولی اختصاصی نیستند؛ کاهش آسیب سد می‌تواند ورود به خون را کاهش دهد.',['مقاومت','زمینه','سد'],[4,6],'پرسش ۱۰ منبع؛ سه بخش')]
mixed=[Q('یک پاسخ خوب تشریحی چگونه از فهرست نام‌ها فراتر می‌رود؟','معیار را تعریف می‌کنم، نام یا مرحله را می‌نویسم، سپس رابطهٔ علت و پیامد و قیدهای مسئله را اضافه می‌کنم؛ نمونه: اندازهٔ ذره، ماندگاری و اهمیت تهویه در فرض سؤال.',['تعریف','رابطه','قید'],[3,5]),Q('آنتی‌ژن، آنزیم و سامانهٔ ترشحی را با مثال تفکیک کنید.','H یک آنتی‌ژن تاژکی، کاتالاز آنزیم حفاظتی و نوع ۳ سامانهٔ انتقال اثرگذار است؛ این‌ها یک دستهٔ ساختاری یکسان نیستند.',['سه مفهوم','مثال'],[3,5])]
finish('استاد نصیری','nasiri','ششم','جلسهٔ شانزدهم؛ پرسش‌ها و پاسخنامه',[([1,2],'جلد و فهرست',[]),([3,5],'انتقال، مثال‌ها، آنتی‌ژن‌ها و شکل فاگوسیت',[1,2,3]),([4,6],'تیفوئید، دهان و کنترل؛ همهٔ ده شماره با زیرسؤال‌ها',[3,4])],mixed,src)
